namespace WarehouseApp.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse and notifies
/// subscribers when it changes. Each SignalR circuit gets its own instance,
/// so concurrent users are fully isolated.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public event Action? OnWarehouseChanged;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnWarehouseChanged?.Invoke();
    }

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } = new List<(string, string)>
    {
        ("WH-001", "Warehouse A — Downtown"),
        ("WH-002", "Warehouse B — Airport"),
        ("WH-003", "Warehouse C — Harbor"),
    };

    public void Dispose()
    {
        OnWarehouseChanged = null;
    }
}

namespace WarehouseApp.Services;

/// <summary>
/// Simulates checking inventory levels. Scoped per circuit so each user's
/// polling is independent.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    /// <summary>
    /// Simulates a database query that returns the count of items below
    /// minimum stock level for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB call with random result 0–15
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }
}

namespace WarehouseApp.Services;

/// <summary>
/// Scoped pub/sub service that allows the polling component to notify all
/// other subscribed components that fresh alert data is available.
/// </summary>
public sealed class AlertNotificationService : IDisposable
{
    public int LatestLowStockCount { get; private set; }

    public event Action? OnAlertDataChanged;

    public void PublishNewCount(int count)
    {
        LatestLowStockCount = count;
        OnAlertDataChanged?.Invoke();
    }

    public void Dispose()
    {
        OnAlertDataChanged = null;
    }
}

