@using WarehouseApp.Services
@inject WarehouseStateService WarehouseState
@rendermode InteractiveServer
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouseSelect"><strong>Current Warehouse:</strong></label>
    <select id="warehouseSelect" @onchange="OnWarehouseSelected" value="@WarehouseState.CurrentWarehouseId">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id" selected="@(wh.Id == WarehouseState.CurrentWarehouseId)">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString() ?? "";
        WarehouseState.SetWarehouse(newId);
    }

    private void HandleWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
    }
}

@using WarehouseApp.Services
@inject AlertNotificationService AlertNotification
@rendermode InteractiveServer
@implements IDisposable

<span class="alert-badge" title="Low-stock items">
    @if (_count > 0)
    {
        <span class="badge bg-danger">@_count</span>
    }
    else
    {
        <span class="badge bg-success">0</span>
    }
    ⚠️ Low Stock
</span>

@code {
    private int _count;

    protected override void OnInitialized()
    {
        _count = AlertNotification.LatestLowStockCount;
        AlertNotification.OnAlertDataChanged += HandleAlertChanged;
    }

    private void HandleAlertChanged()
    {
        _count = AlertNotification.LatestLowStockCount;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertNotification.OnAlertDataChanged -= HandleAlertChanged;
    }
}

