﻿@page "/"
@using WarehouseApp.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService InventoryAlerts
@inject AlertNotificationService AlertNotification
@rendermode InteractiveServer
@implements IDisposable

<PageTitle>Dashboard — @WarehouseState.CurrentWarehouseId</PageTitle>

<h1>📊 Warehouse Dashboard</h1>
<p>Viewing data for: <strong>@GetWarehouseName()</strong></p>

<div class="dashboard-card">
    <h3>Low-Stock Alerts</h3>
    <p class="big-number @(_lowStockCount > 5 ? "text-danger" : "text-success")">
        @_lowStockCount
    </p>
    <p>items below minimum level</p>
    <small>Polling every 10 seconds. Last checked: @_lastChecked?.ToString("HH:mm:ss")</small>
</div>

@code {
    private int _lowStockCount;
    private DateTime? _lastChecked;
    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
        AlertNotification.OnAlertDataChanged += HandleAlertChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await PollNow();
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts?.Cancel();
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _ = Task.Run(async () =>
        {
            while (!token.IsCancellationRequested)
            {
                await Task.Delay(TimeSpan.FromSeconds(10), token);
                if (token.IsCancellationRequested) break;
                await PollNow();
            }
        }, token);
    }

    private async Task PollNow()
    {
        var count = await InventoryAlerts.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        _lastChecked = DateTime.Now;
        _lowStockCount = count;

        // Publish to all subscribers (sidebar badge, other components)
        AlertNotification.PublishNewCount(count);

        await InvokeAsync(StateHasChanged);
    }

    private void HandleWarehouseChanged()
    {
        // Restart polling immediately for the new warehouse
        _cts?.Cancel();
        _ = InvokeAsync(async () =>
        {
            await PollNow();
            StartPolling();
        });
    }

    private void HandleAlertChanged()
    {
        _lowStockCount = AlertNotification.LatestLowStockCount;
        InvokeAsync(StateHasChanged);
    }

    private string GetWarehouseName()
    {
        return WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
            ?? WarehouseState.CurrentWarehouseId;
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        AlertNotification.OnAlertDataChanged -= HandleAlertChanged;
    }
}

