arguments.file_text:
@page "/inventory"
@using WarehouseApp.Services
@inject WarehouseStateService WarehouseState
@rendermode InteractiveServer
@implements IDisposable

<PageTitle>Inventory — @WarehouseState.CurrentWarehouseId</PageTitle>

<h1>📦 Inventory</h1>
<p>Showing inventory for: <strong>@GetWarehouseName()</strong></p>
<p><em>Navigate back to the Dashboard to start low-stock polling.</em></p>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleChanged;
    }

    private void HandleChanged() => InvokeAsync(StateHasChanged);

    private string GetWarehouseName()
    {
        return WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
            ?? WarehouseState.CurrentWarehouseId;
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleChanged;
    }
}

arguments.new_str:
.page {
    display: flex;
    min-height: 100vh;
}

.sidebar {
    width: 260px;
    background: #1e293b;
    color: #f1f5f9;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.sidebar-header h4 {
    margin: 0;
}

.sidebar-selector select {
    width: 100%;
    padding: 0.4rem;
    border-radius: 4px;
}

.nav-menu {
    list-style: none;
    padding: 0;
}

.nav-menu li {
    margin: 0.5rem 0;
}

.nav-menu a {
    color: #93c5fd;
    text-decoration: none;
}

.main-content {
    flex: 1;
    padding: 2rem;
}

.dashboard-card {
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    padding: 1.5rem;
    max-width: 400px;
    margin-top: 1rem;
}

.big-number {
    font-size: 3rem;
    font-weight: bold;
    margin: 0.5rem 0;
}

.text-danger { color: #dc2626; }
.text-success { color: #16a34a; }

.badge {
    display: inline-block;
    padding: 0.2em 0.6em;
    border-radius: 10px;
    font-size: 0.8rem;
    color: #fff;
}

.bg-danger { background: #dc2626; }
.bg-success { background: #16a34a; }

.warehouse-selector {
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
}

